  's6705140062_kiosk'@'localhost', 's6705140062_kiosk'@'%',
  's6705140062_intern'@'%', 's6705140062_intern'@'localhost',
  's6705140062_etl'@'localhost', 's6705140062_etl'@'%',
  's6705140062_report'@'localhost', 's6705140062_report'@'%';

